css:
.d-rot{position:relative;width:300px;height:150px;color:var(--ink)}
.d-rot-stage{position:absolute;left:14px;top:16px;width:200px;height:112px;border:1px dashed var(--line);border-radius:6px}
.d-rot-axis-h{position:absolute;left:0;right:0;top:50%;height:1px;background:var(--line)}
.d-rot-axis-v{position:absolute;top:0;bottom:0;left:50%;width:1px;background:var(--line)}
.d-rot-card{position:absolute;left:50%;top:50%;width:112px;height:72px;margin:-36px 0 0 -56px;display:flex;flex-direction:column;justify-content:space-between;padding:8px 10px;background:var(--paper);border:1px solid var(--ink);border-radius:6px;box-shadow:0 1px 0 var(--line);cursor:grab;touch-action:none;user-select:none;will-change:transform}
.d-rot-card b{font-size:11px;font-weight:650;letter-spacing:.02em}
.d-rot-card em{font-style:normal;font-family:var(--mono);font-size:9px;letter-spacing:.04em;color:var(--faint)}
.d-rot-card[data-drag]{cursor:grabbing;box-shadow:0 12px 24px -8px #20241e26}
.d-rot-card:focus-visible{outline:1px solid var(--ink);outline-offset:2px}
.d-rot-num{position:absolute;right:14px;top:16px;font-family:var(--mono);font-size:21px;line-height:1.05;letter-spacing:-.02em;color:#2b4b8f}
.d-rot-hint{position:absolute;left:14px;bottom:8px;margin:0;font-family:var(--mono);font-size:9px;line-height:1.6;color:var(--faint)}

init:
root => {
  const box = root.querySelector('.d-rot');
  if (!box || box.dataset.ready) return;
  box.dataset.ready = '1';
  const card = box.querySelector('.d-rot-card');
  const num = box.querySelector('.d-rot-num');
  const hint = box.querySelector('.d-rot-hint');
  const IDLE = 'Shift + 拖 · 0° 基准';
  let rot = 0, drag = null;

  function render(v, animate) {
    rot = v;
    card.style.transition = animate ? 'transform .28s cubic-bezier(.34,1.56,.64,1)' : 'none';
    card.style.transform = 'rotate(' + v.toFixed(1) + 'deg)';
    num.textContent = Math.round(v) + '°';
    hint.textContent = Math.round(v) === 0 ? IDLE : '已转 ' + Math.round(v) + '° · 15° 一档 · Enter 归零';
  }
  function down(e) {
    if (!e.shiftKey || drag) return;
    e.preventDefault();
    card.focus({ preventScroll: true });
    const r = card.getBoundingClientRect();
    const c = { x: r.left + r.width / 2, y: r.top + r.height / 2 };
    drag = { c: c, a0: Math.atan2(e.clientY - c.y, e.clientX - c.x), r0: rot };
    card.setPointerCapture(e.pointerId);
    card.dataset.drag = '1';
    render(rot, false);
  }
  function move(e) {
    if (!drag) return;
    const a = Math.atan2(e.clientY - drag.c.y, e.clientX - drag.c.x);
    render(drag.r0 + (a - drag.a0) * 180 / Math.PI, false);
  }
  function up() {
    if (!drag) return;
    drag = null;
    delete card.dataset.drag;
    const snap = Math.round(rot / 15) * 15;
    render(Math.abs(rot - snap) < 6 ? snap : rot, true);
  }
  function key(e) {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      render(0, true);
      return;
    }
    const d = e.key === 'ArrowLeft' ? -15 : e.key === 'ArrowRight' ? 15 : 0;
    if (!d) return;
    e.preventDefault();
    render(rot + d, true);
  }

  card.addEventListener('pointerdown', down);
  card.addEventListener('pointermove', move);
  card.addEventListener('pointerup', up);
  card.addEventListener('pointercancel', up);
  card.addEventListener('keydown', key);
  render(0, false);
}
